// Allocate a writable MD5Context and initialize it for a new computation
struct MD5Context *context = new MD5Context;
// MD5Init requires a valid, writable context pointer
MD5Init(context);
// Track lifecycle/state for downstream stubs
FUZZ_SET_ATTR_INT(context, "initialized", 1);
FUZZ_SET_ATTR_INT(context, "finalized", 0);
FUZZ_SET_ATTR_INT(context, "total_len", 0);
// Validation: The context is allocated and initialized; returned for reuse by MD5Update/MD5Final.

// Enforce that the context was initialized and not yet finalized
int initialized = FUZZ_GET_ATTR_INT(context, "initialized");
int finalized = FUZZ_GET_ATTR_INT(context, "finalized");
if (!initialized || finalized) { FUZZ_BAIL(); }

// Generate input buffer; len may be zero (API no-op allowed)
std::string data = FUZZ_PARAM_STR();
unsigned int len = (unsigned int)(data.size() == 0 ? 0 : (*FUZZ_PARAM(unsigned int) % (data.size() + 1u)));
const unsigned char *buf = reinterpret_cast<const unsigned char *>(data.data());

// Call target function
MD5Update(context, buf, len);

// Track total input length (avoid signed int overflow in metadata)
int total = FUZZ_GET_ATTR_INT(context, "total_len");
if (len <= 0x7fffffff) {
    int inc = (int)len;
    if (inc > 0 && total > 0x7fffffff - inc) {
        total = 0x7fffffff;
    } else {
        total += inc;
    }
    FUZZ_SET_ATTR_INT(context, "total_len", total);
}
// Validation: Preconditions (initialized and not finalized) are enforced; context is preserved for further operations.

// Enforce that the context was initialized and not yet finalized
int initialized = FUZZ_GET_ATTR_INT(context, "initialized");
int finalized = FUZZ_GET_ATTR_INT(context, "finalized");
if (!initialized || finalized) { FUZZ_BAIL(); }

// Provide a writable 16-byte output buffer for the digest
unsigned char digest[16];
MD5Final(digest, context);

// Update lifecycle: mark finalized; require reinit before further updates/final
FUZZ_SET_ATTR_INT(context, "finalized", 1);
FUZZ_SET_ATTR_INT(context, "initialized", 0);
// Validation: Digest buffer size satisfied; state marked finalized for downstream checks.

// Generate state (4 words) and one message block (16 words)
uint32_t (*state_src)[4] = FUZZ_PARAM(uint32_t[4]);
uint32_t (*block_src)[16] = FUZZ_PARAM(uint32_t[16]);

// Make local copies to ensure proper writable/readable buffers of exact sizes
uint32_t buf[4];
uint32_t in[16];
for (int i = 0; i < 4; ++i) { buf[i] = (*state_src)[i]; }
for (int i = 0; i < 16; ++i) { in[i] = (*block_src)[i]; }

// Call the low-level compression step. Endianness expectations are unknown; we simply supply random words.
MD5Transform(buf, in);
